           $$Why can a single rebase pause for a conflict more than once?$$, NULL, NULL,
           $$Because rebase replays commits one at a time, a conflict can occur on any individual commit in the sequence — Git pauses exactly at each commit where one occurs, which can mean stopping more than once in the same rebase.$$, 'n8n-ai-judge', '2026-08-29 21:25:57.374362',
           now(), now()
    FROM topic
    WHERE slug = 'merge-conflicts'
      AND NOT EXISTS (SELECT 1 FROM existing_q5)
