    INSERT INTO question_option (question_id, option_text, is_correct, sort_order)
    SELECT target_q5.id, v.option_text, v.is_correct, v.sort_order
    FROM target_q5
             CROSS JOIN (VALUES
    ($$Because rebase replays commits one at a time, and a conflict can occur on any individual commit in the sequence, so Git pauses at each one that conflicts.$$, TRUE, 0),
    ($$Because Git deliberately re-triggers the same conflict a second time as a safety check.$$, FALSE, 1),
    ($$Because every rebase always produces exactly two conflicts.$$, FALSE, 2),
    ($$Because conflicts during a rebase are unrelated to the commits being replayed.$$, FALSE, 3)
